export function checkedJob(job,environment=process.env) {
 if(!Object.hasOwn(workflowJobs,job))throw Error('准确远端Job身份无效');
 if(environment.GITHUB_REPOSITORY!=='crcfrcn/citizensdk')throw Error('准确远端Job仓库身份无效');
 return workflowJobs[job];
}
export function workflowStep(job,index,environment=process.env) {
 const current=checkedJob(job,environment);
 if(!/^(?:0|[1-9][0-9]*)$/.test(String(index??''))||!Object.hasOwn(current.steps,String(index)))throw Error('准确远端Job阶段无效');
 return current.steps[String(index)];
}
export function runExactWorkflowStep(job,index,environment=process.env,run=spawnSync) {
 const step=workflowStep(job,index,environment),command=step.shell==='pwsh'?'pwsh':(process.platform==='win32'?'bash':'/bin/bash');
 const args=step.shell==='pwsh'?['-NoLogo','-NoProfile','-NonInteractive','-Command',step.source]:['--noprofile','--norc','-e','-o','pipefail','-c',step.source];
 const result=run(command,args,{cwd:process.cwd(),env:environment,stdio:'inherit'});
 if(result.error)throw Error('准确远端Job阶段无法启动');return result.status??1;
}
export async function runJobCLI(values,environment=process.env) {
 return withFixedWork('build',()=>runJobTask(values,environment),{environment,retain:true});
}
async function runJobTask(values,environment=process.env) {
 const [job,command,index,...extra]=values;checkedJob(job,environment);
 if(extra.length)throw Error('准确远端Job参数无效');

 if(!/^[0-9a-f]{40}$/.test(environment.SOURCE_SHA||'')||!/^[1-9][0-9]*$/.test(environment.CI_RUN_ID||'')||!/^\d+\.\d{1,2}\.\d{1,2}$/.test(environment.SOFTWARE_VERSION||'')||environment.VERSION_TAG!=='citizensdk-sdk-v'+environment.SOFTWARE_VERSION)throw Error('准确Release候选无效');
 if(command!=='workflow-step')throw Error('准确Release Job只接受workflow-step');
 if(command==="workflow-step")return runExactWorkflowStep(job,index,environment);
 throw Error("准确远端Job动作无效");
}
if(!(process.env.NODE_TEST_CONTEXT && process.argv.length === 2)&&!process.execArgv.some(value=>/^(?:-e|--eval(?:=|$)|--input-type(?:=|$))/u.test(value)) && process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 try {Object.assign(process.env,remoteEnvironment());process.exitCode=await runJobCLI(process.argv.slice(2));}
 catch(error){console.error(error.message);process.exitCode=1;}
}

// 正式实现结束；仅直接使用 node --test 执行本文件时注册以下回归。
if (process.env.NODE_TEST_CONTEXT && process.argv.length === 2 && !process.execArgv.some(value=>/^(?:-e|--eval(?:=|$)|--input-type(?:=|$))/u.test(value)) && process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
const {default:assert}=await import('node:assert/strict');
const {default:test}=await import('node:test');
test('远端作业身份与阶段边界在运行Shell前拒绝',()=>{
 const env={GITHUB_REPOSITORY:'crcfrcn/citizensdk'};
 for(const name of Object.keys(workflowJobs)){
  for(const index of ['-1','01','../0','9999'])assert.throws(()=>workflowStep(name,index,env));
  assert.throws(()=>workflowStep(name,Object.keys(workflowJobs[name].steps)[0],{GITHUB_REPOSITORY:'foreign/repo'}));
 }
 assert.throws(()=>checkedJob('../android',env));
});
test('远端入口转交准确正文、Shell和退出码',()=>{
 const env={GITHUB_REPOSITORY:'crcfrcn/citizensdk'};
 for(const [name,current]of Object.entries(workflowJobs))for(const [index,step]of Object.entries(current.steps)){
  let calls=0;const status=runExactWorkflowStep(name,index,env,(command,args,options)=>{
   calls++;assert.equal(args.at(-1),step.source);assert.equal(command,step.shell==='pwsh'?'pwsh':process.platform==='win32'?'bash':'/bin/bash');assert.equal(options.env,env);return {status:7};
  });assert.equal(status,7);assert.equal(calls,1);
 }
});

}
